app.listen(config.port, () => {
  console.log(`Server listening on port ${config.port}`);
});
```

This gives you:

- Centralized config,
- Explicit required secrets,
- Early failure if secrets are missing.

### 4. Moving to a secrets manager (high‑level guidance)

For production, you’d ideally **not** rely on `.env` files but on a managed secrets service (AWS, GCP, Azure, Vault, etc.), exposing them as environment variables at runtime.

Example (AWS Secrets Manager + SSM Parameter Store pattern):

```js
// config/loadSecrets.js
import { SSMClient, GetParametersByPathCommand } from '@aws-sdk/client-ssm';

const ssm = new SSMClient({});

export async function loadSecrets(prefix = '/my-app/prod/') {
  const command = new GetParametersByPathCommand({
    Path: prefix,
    WithDecryption: true,
    Recursive: true,
  });
  const response = await ssm.send(command);

  for (const param of response.Parameters || []) {
    const key = param.Name.replace(prefix, '').toUpperCase(); // e.g. "JWT_SECRET"
    process.env[key] = param.Value;
  }
}
```

Then in your entrypoint:

```js
import { loadSecrets } from './config/loadSecrets.js';
import { config } from './config/secrets.js';

(async () => {
  if (process.env.NODE_ENV === 'production') {
    await loadSecrets('/my-app/prod/');
  } else {
    // local dev
    await import('dotenv/config');
  }

  const { default: app } = await import('./app.js');
  app.listen(config.port, () => {
    console.log(`Server running on port ${config.port}`);
  });
})();
```

This pattern:

- Uses `.env` only for local,
- Uses a secrets manager for prod,
- Still centralizes access via `config`.

