### Node.js script: `preview-env-secrets.js`

```js
// preview-env-secrets.js
import fs from 'fs';

const envPath = process.argv[2] || '.env';

if (!fs.existsSync(envPath)) {
  console.error(`File not found: ${envPath}`);
  process.exit(1);
}

const content = fs.readFileSync(envPath, 'utf8');

function looksLikeSecret(name) {
  const secretKeywords = [
    'SECRET', 'KEY', 'TOKEN', 'PASSWORD', 'PWD', 'PASS',
    'API_KEY', 'AUTH', 'PRIVATE', 'ACCESS_KEY', 'CLIENT_SECRET',
    'DB_URL', 'DATABASE_URL', 'CONNECTION_STRING'
  ];
  const upper = name.toUpperCase();
  return secretKeywords.some(k => upper.includes(k));
}

function redactValue(value) {
  const trimmed = value.trim();
  if (trimmed.length <= 8) return '********'; // too short; fully mask
  const first = trimmed.slice(0, 4);
  const last = trimmed.slice(-4);
  return `${first}****${last}`;
}

console.log(`Reading secrets from ${envPath}...\n`);

content.split('\n').forEach((line) => {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith('#')) return;

  const eqIndex = trimmed.indexOf('=');
  if (eqIndex === -1) return;

  const name = trimmed.slice(0, eqIndex).trim();
  let value = trimmed.slice(eqIndex + 1);

  // Remove surrounding quotes
  if ((value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))) {
    value = value.slice(1, -1);
  }

  if (!looksLikeSecret(name)) return;

  const preview = redactValue(value);
  console.log(`${name}=${preview}`);
});
```

